.pp textarea:focus,.pp input:focus{outline:none;border-color:var(--pp-accent);box-shadow:0 0 0 3px rgba(11,92,173,.18)}
.pp code{background:var(--pp-soft);border-radius:3px;padding:0 4px;font-size:.92em}
