.pp-spin{width:26px;height:26px;border:3px solid var(--pp-line);border-top-color:var(--pp-accent);border-radius:50%;animation:pp-spin .8s linear infinite;flex:none}
@keyframes pp-spin{to{transform:rotate(360deg)}}
