    if (dataEl.getAttribute('data-pp-ready')) { return; }
    var data;
    try { data = JSON.parse(dataEl.value); } catch (e) { return; }
    dataEl.setAttribute('data-pp-ready', '1');
    var $ = function (id) { return document.getElementById(id); };
