.pp-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media (max-width:760px){.pp-grid{grid-template-columns:1fr}}
.pp label{display:block;font-weight:600;font-size:13px;margin:18px 0 6px}
